from __future__ import annotations

from contextlib import contextmanager

import pytest

import stamina


def test_guess_name() -> None:
    def local_func() -> None:
        return None

    class Foo:
        def method(self) -> None:
            return None

    foo = Foo()

    assert "local_func" in stamina.guess_name(local_func)
    assert "Foo.method" in stamina.guess_name(foo.method)


def test_hook_management_roundtrip() -> None:
    def hook(details: stamina.RetryDetails) -> None:
        return None

    stamina.set_on_retry_hooks([hook])
    assert stamina.get_on_retry_hooks() == (hook,)

    stamina.set_on_retry_hooks([])
    assert stamina.get_on_retry_hooks() == ()

    stamina.set_on_retry_hooks(None)
    assert stamina.get_on_retry_hooks()


def test_context_manager_hooks_are_entered_and_exited() -> None:
    entered = False
    exited = False

    @contextmanager
    def hook(details: stamina.RetryDetails):
        nonlocal entered, exited
        entered = True
        yield
        exited = True

    stamina.set_on_retry_hooks([hook])

    @stamina.retry(on=ValueError, attempts=2, wait_max=0)
    def func() -> None:
        raise ValueError("retry")

    with pytest.raises(ValueError):
        func()

    assert entered
    assert exited


def test_prometheus_counter_can_be_initialized() -> None:
    counter = stamina.get_prometheus_counter()
    assert counter is not None


def test_init_structlog_returns_callable() -> None:
    hook = stamina.init_structlog()
    assert callable(hook)

