from __future__ import annotations

import stamina


class TemporaryHTTPError(RuntimeError):
    pass


attempts = 0


@stamina.retry(on=TemporaryHTTPError, attempts=3, wait_max=0)
def fetch_document() -> dict[str, str]:
    global attempts
    attempts += 1
    if attempts < 2:
        raise TemporaryHTTPError("upstream is temporarily unavailable")
    return {"status": "ok", "body": "hello"}


if __name__ == "__main__":
    print(fetch_document())
